import { Injectable } from '@angular/core';
import { Session } from '../models/session.models';

/**
 * Simulated sample practices shipped with the app (generated by
 * tools/simulate). Read-only, loaded once from the app's own files.
 */
@Injectable({ providedIn: 'root' })
export class SampleRepository {
  private cache: Promise<Session[]> | null = null;

  list(): Promise<Session[]> {
    this.cache ??= fetch('samples/sample-practices.json')
      .then((r) => (r.ok ? r.json() : { sessions: [] }))
      .then((d: { sessions?: Session[] }) =>
        (d.sessions ?? []).map((s) => ({ ...s, sample: true })),
      )
      .catch(() => []);
    return this.cache;
  }

  async get(id: string): Promise<Session | null> {
    return (await this.list()).find((s) => s.id === id) ?? null;
  }
}
